sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?title ?director ?deathDate
WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/A_Mother's_Devotion> 
    <http://dbpedia.org/resource/Painted_Boats>
  }
  # title (prefer dbp:name)
  OPTIONAL { ?film dbp:name ?title . }
  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?director . }
  # if dbp:director missing, try dbo:director
  OPTIONAL { 
    FILTER (!BOUND(?director))
    ?film dbo:director ?director .
  }
  # death date of the director (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?deathDate . }
  # fallback to dbo:deathDate
  OPTIONAL { 
    FILTER (!BOUND(?deathDate))
    ?director dbo:deathDate ?deathDate .
  }
}
LIMIT 100

